Íme egy teljes implementáció, amely a Grok 4 Heavy multi-agent architektúráját implementálja GLM-4.7-tel, 15 független ágenssel és különböző API kulcsokkal:[1][2][3]

```python
import os
import json
import asyncio
from typing import List, Dict, Tuple
from collections import Counter
from flask import Flask, Response, request, send_from_directory
from cerebras.cloud.sdk import AsyncCerebras

app = Flask(__name__, static_folder=".")

# 15 különböző API kulcs környezeti változókból
API_KEYS = [
    os.environ.get(f"CEREBRAS_API_KEY_{i}") 
    for i in range(1, 16)
]

# Agent clients inicializálása
agents = [
    AsyncCerebras(api_key=key) 
    for key in API_KEYS if key
]

# Rate limiting: max 10 párhuzamos hívás egyszerre
SEMAPHORE = asyncio.Semaphore(10)

async def agent_reasoning(
    agent_id: int,
    client: AsyncCerebras,
    user_message: str,
    context_from_others: List[str] = None
) -> Dict:
    """
    Egyetlen agent futtatása reasoning-gel.
    Hasonló a Grok 4 Heavy egy ágensének működéséhez.
    """
    async with SEMAPHORE:
        try:
            # Kontextus építése más agensek eredményeiből
            system_prompt = """Mindig magyarul válaszolj, tökéletes változatos természetes anyanyelvi magyarral.

Egy 15 fős multi-agent rendszer tagja vagy, amely együttműködik összetett problémák megoldásában.
A feladatod:
1. Önállóan elemezd a problémát
2. Gondold végig a megoldási lehetőségeket
3. Ha más agensek eredményeit látod, értékeld és építs rájuk
4. Keress alternatív megközelítéseket
5. Legyen kritikus a saját érvelésedet illetően

Ha más agensek eredményeit látod, NE egyszerűen ismételd meg őket, hanem:
- Ellenőrizd a logikájukat
- Keress hibákat vagy hiányosságokat  
- Adj hozzá új perspektívákat
- Finomítsd vagy javítsd a megoldást"""

            if context_from_others:
                system_prompt += f"\n\nMás agensek eddigi eredményei:\n{chr(10).join(context_from_others)}"

            messages = [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_message}
            ]

            reasoning_steps = []
            content_parts = []

            stream = await client.chat.completions.create(
                messages=messages,
                model="zai-glm-4.7",
                stream=True,
                max_completion_tokens=32000,
                temperature=0.8,  # Magasabb diverzitásért
                top_p=0.95,
                disable_reasoning=False,
                reasoning_format="parsed",
                clear_thinking=False
            )

            async for chunk in stream:
                if chunk.choices and len(chunk.choices) > 0:
                    delta = chunk.choices[0].delta
                    if hasattr(delta, "reasoning") and delta.reasoning:
                        reasoning_steps.append(delta.reasoning)
                    if delta.content:
                        content_parts.append(delta.content)

            return {
                "agent_id": agent_id,
                "reasoning": "".join(reasoning_steps),
                "content": "".join(content_parts),
                "success": True
            }

        except Exception as e:
            return {
                "agent_id": agent_id,
                "error": str(e),
                "success": False
            }


async def multi_agent_consensus(
    user_message: str,
    num_agents: int = 15,
    rounds: int = 2
) -> Dict:
    """
    Multi-round multi-agent reasoning Grok 4 Heavy stílusban.

    Round 1: Minden agent önállóan dolgozik
    Round 2: Agensek látják mások eredményeit és finomítanak
    Végül: Weighted aggregation a legjobb válaszért
    """

    all_results = []

    # ROUND 1: Független párhuzamos reasoning
    print(f"🚀 Round 1: {num_agents} agent független feldolgozása...")

    tasks_round1 = [
        agent_reasoning(i, agents[i], user_message)
        for i in range(min(num_agents, len(agents)))
    ]

    results_round1 = await asyncio.gather(*tasks_round1)
    successful_round1 = [r for r in results_round1 if r.get("success")]

    print(f"✅ Round 1 kész: {len(successful_round1)}/{num_agents} agent sikeres")
    all_results.extend(successful_round1)

    if rounds > 1 and len(successful_round1) >= 3:
        # ROUND 2: Cross-pollination - agensek látják mások eredményeit
        print(f"🔄 Round 2: Kereszt-validáció és finomítás...")

        # Top 5 eredmény kiválasztása kontextusnak
        top_contexts = [
            f"Agent {r['agent_id']}: {r['content'][:500]}..."
            for r in successful_round1[:5]
        ]

        # Második kör - fele annyi agent, de látják az első kör eredményeit
        tasks_round2 = [
            agent_reasoning(
                i + num_agents,  # Új agent ID-k
                agents[i % len(agents)],  # Újrahasználjuk az API kulcsokat
                user_message,
                context_from_others=top_contexts
            )
            for i in range(min(num_agents // 2, len(agents)))
        ]

        results_round2 = await asyncio.gather(*tasks_round2)
        successful_round2 = [r for r in results_round2 if r.get("success")]

        print(f"✅ Round 2 kész: {len(successful_round2)} agent finomított")
        all_results.extend(successful_round2)

    return {
        "total_agents": len(all_results),
        "results": all_results,
        "rounds": rounds
    }


def weighted_synthesis(results: List[Dict], user_message: str) -> Dict:
    """
    Súlyozott szintézis az agent eredményekből.

    Súlyozási faktorok:
    - Reasoning hossza (mélyebb gondolkodás)
    - Tartalom komplexitása
    - Round 2 eredmények magasabb súllyal (finomított)
    """

    if not results:
        return {
            "synthesis": "Nem sikerült eredményt generálni.",
            "confidence": 0.0
        }

    weighted_results = []

    for r in results:
        weight = 1.0

        # Round 2 eredmények 1.5x súly
        if r.get("agent_id", 0) >= 15:
            weight *= 1.5

        # Hosszabb reasoning magasabb súly (max 2x)
        reasoning_len = len(r.get("reasoning", ""))
        if reasoning_len > 1000:
            weight *= 1.5
        elif reasoning_len > 500:
            weight *= 1.2

        # Hosszabb válasz (részletesebb) magasabb súly
        content_len = len(r.get("content", ""))
        if content_len > 1000:
            weight *= 1.3

        weighted_results.append({
            "result": r,
            "weight": weight
        })

    # Rendezés súly szerint
    weighted_results.sort(key=lambda x: x["weight"], reverse=True)

    # Top 3 súlyozott kombináció
    top_3 = weighted_results[:3]

    synthesis_parts = []
    total_weight = sum(wr["weight"] for wr in top_3)

    for i, wr in enumerate(top_3, 1):
        contribution = (wr["weight"] / total_weight) * 100
        synthesis_parts.append(
            f"**Agent {wr['result']['agent_id']}** (hozzájárulás: {contribution:.1f}%):\n"
            f"{wr['result']['content']}\n"
        )

    # Reasoning összesítés
    all_reasoning = [
        f"Agent {r['agent_id']} gondolatmenete:\n{r.get('reasoning', 'N/A')[:500]}..."
        for r in results[:5]  # Top 5 reasoning
    ]

    return {
        "synthesis": "\n\n".join(synthesis_parts),
        "reasoning_summary": "\n\n---\n\n".join(all_reasoning),
        "total_agents": len(results),
        "confidence": min(len(results) / 15, 1.0)  # 0-1 skála
    }


@app.route("/")
def index():
    return send_from_directory(".", "index.html")


@app.route("/chat", methods=["POST"])
def chat():
    data = request.get_json()
    user_message = data.get("message", "")
    num_agents = data.get("num_agents", 15)  # Konfigurálható agent szám
    rounds = data.get("rounds", 2)  # Konfigurálható round szám

    def generate():
        # Event loop létrehozása a szinkron kontextusban
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)

        try:
            # Státusz küldése
            yield f"data: {json.dumps({'type': 'status', 'content': f'🚀 {num_agents} agent indítása...'})}\n\n"

            # Multi-agent feldolgozás futtatása
            multi_result = loop.run_until_complete(
                multi_agent_consensus(user_message, num_agents, rounds)
            )

            # Minden agent reasoning-jét streameljük
            for result in multi_result["results"]:
                if result.get("success"):
                    # Agent reasoning
                    if result.get("reasoning"):
                        payload = json.dumps({
                            "type": "reasoning",
                            "agent_id": result["agent_id"],
                            "content": f"**Agent {result['agent_id']} gondolkodása:**\n\n{result['reasoning']}"
                        })
                        yield f"data: {payload}\n\n"

                    # Agent tartalom
                    payload = json.dumps({
                        "type": "agent_response",
                        "agent_id": result["agent_id"],
                        "content": f"**Agent {result['agent_id']} válasza:**\n\n{result['content']}"
                    })
                    yield f"data: {payload}\n\n"

            # Súlyozott szintézis
            yield f"data: {json.dumps({'type': 'status', 'content': '🔮 Szintézis készítése...'})}\n\n"

            synthesis = weighted_synthesis(multi_result["results"], user_message)

            # Reasoning összefoglaló
            payload = json.dumps({
                "type": "synthesis_reasoning",
                "content": f"## 🧠 Kollektív Gondolkodás\n\n{synthesis['reasoning_summary']}"
            })
            yield f"data: {payload}\n\n"

            # Végső szintézis
            payload = json.dumps({
                "type": "synthesis",
                "content": f"## 🎯 Végső Szintézis ({multi_result['total_agents']} agent alapján)\n\n{synthesis['synthesis']}\n\n**Konfidencia:** {synthesis['confidence']*100:.0f}%"
            })
            yield f"data: {payload}\n\n"

        except Exception as e:
            error_payload = json.dumps({
                "type": "error",
                "content": f"❌ Hiba: {str(e)}"
            })
            yield f"data: {error_payload}\n\n"

        finally:
            loop.close()
            yield "data: [DONE]\n\n"

    return Response(generate(), mimetype="text/event-stream")


@app.route("/health", methods=["GET"])
def health():
    """Health check endpoint"""
    return {
        "status": "healthy",
        "agents": len(agents),
        "api_keys_configured": len([k for k in API_KEYS if k])
    }


if __name__ == "__main__":
    print(f"🤖 Multi-Agent System indítása...")
    print(f"📊 Elérhető agensek: {len(agents)}")
    print(f"🔑 Konfigurált API kulcsok: {len([k for k in API_KEYS if k])}")
    app.run(host="0.0.0.0", port=5000, debug=True)
```

