                sendMessage();
            }
        });

        // Kezdő üzenet
        addMessage(
            '👋 Üdvözöllek a Multi-Agent GLM-4.7 Heavy rendszerben!<br><br>' +
            '💡 15 független AI agent dolgozik együtt a kérdéseiden<br>' +
