import os
import json
import asyncio
from typing import List, Dict, Optional
from datetime import datetime
from flask import Flask, Response, request, send_from_directory, jsonify
from flask_cors import CORS
from cerebras.cloud.sdk import AsyncCerebras
import logging

app = Flask(__name__, static_folder=".")
CORS(app)

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

API_KEYS = [
    os.environ.get(f"CEREBRAS_API_KEY_{i}")
    for i in range(1, 16)
]

API_KEYS = [key for key in API_KEYS if key]

if not API_KEYS:
    API_KEYS = [os.environ.get("CEREBRAS_API_KEY")]
    API_KEYS = [key for key in API_KEYS if key]

agents = [AsyncCerebras(api_key=key) for key in API_KEYS]

SEMAPHORE = asyncio.Semaphore(10)

conversation_history = {}


async def agent_reasoning(
    agent_id: int,
    client: AsyncCerebras,
    user_message: str,
    conversation_context: List[Dict] = None,
    context_from_others: List[str] = None,
    temperature: float = 0.8,
    max_tokens: int = 32000
) -> Dict:
    async with SEMAPHORE:
        try:
            system_prompt = """Mindig magyarul válaszolj, tökéletes változatos természetes anyanyelvi magyarral.

Egy 15 fős multi-agent rendszer tagja vagy, amely együttműködik összetett problémák megoldásában.

A feladatod:
1. Önállóan elemezd a problémát
2. Gondold végig a megoldási lehetőségeket
3. Ha más agensek eredményeit látod, értékeld és építs rájuk
4. Keress alternatív megközelítéseket
5. Legyen kritikus a saját érvelésedet illetően

Ha más agensek eredményeit látod, NE egyszerűen ismételd meg őket, hanem:
- Ellenőrizd a logikájukat
- Keress hibákat vagy hiányosságokat
- Adj hozzá új perspektívákat
- Finomítsd vagy javítsd a megoldást"""

            if context_from_others:
                system_prompt += f"\n\nMás agensek eddigi eredményei:\n{chr(10).join(context_from_others)}"

            messages = []

            if conversation_context:
                messages.extend(conversation_context)

            messages.append({"role": "system", "content": system_prompt})
            messages.append({"role": "user", "content": user_message})

            reasoning_steps = []
            content_parts = []

            stream = await client.chat.completions.create(
                messages=messages,
                model="zai-glm-4.7",
                stream=True,
                max_completion_tokens=max_tokens,
                temperature=temperature,
                top_p=0.95,
                disable_reasoning=False,
                reasoning_format="parsed",
                clear_thinking=False
            )

            async for chunk in stream:
                if chunk.choices and len(chunk.choices) > 0:
                    delta = chunk.choices[0].delta
                    if hasattr(delta, "reasoning") and delta.reasoning:
                        reasoning_steps.append(delta.reasoning)
                    if delta.content:
                        content_parts.append(delta.content)

            return {
                "agent_id": agent_id,
                "reasoning": "".join(reasoning_steps),
                "content": "".join(content_parts),
                "success": True,
                "timestamp": datetime.now().isoformat()
            }

        except Exception as e:
            logger.error(f"Agent {agent_id} error: {str(e)}")
            return {
                "agent_id": agent_id,
                "error": str(e),
                "success": False,
                "timestamp": datetime.now().isoformat()
            }


async def multi_agent_consensus(
    user_message: str,
    num_agents: int = 15,
    rounds: int = 2,
    conversation_context: List[Dict] = None,
    temperature: float = 0.8
) -> Dict:
    all_results = []

    effective_agents = min(num_agents, len(agents))

    logger.info(f"Starting Round 1 with {effective_agents} agents")

    tasks_round1 = [
        agent_reasoning(
            i,
            agents[i % len(agents)],
            user_message,
            conversation_context=conversation_context,
            temperature=temperature
        )
        for i in range(effective_agents)
    ]

    results_round1 = await asyncio.gather(*tasks_round1, return_exceptions=True)

    successful_round1 = [
        r for r in results_round1
        if isinstance(r, dict) and r.get("success")
    ]

    logger.info(f"Round 1 complete: {len(successful_round1)}/{effective_agents} successful")
    all_results.extend(successful_round1)

    if rounds > 1 and len(successful_round1) >= 3:
        logger.info(f"Starting Round 2 with refinement")

        top_contexts = [
            f"Agent {r['agent_id']}: {r['content'][:500]}..."
            for r in successful_round1[:5]
        ]

        round2_count = min(effective_agents // 2, len(agents))

        tasks_round2 = [
            agent_reasoning(
                i + effective_agents,
                agents[i % len(agents)],
                user_message,
                conversation_context=conversation_context,
                context_from_others=top_contexts,
                temperature=temperature * 0.9
            )
            for i in range(round2_count)
        ]

        results_round2 = await asyncio.gather(*tasks_round2, return_exceptions=True)

        successful_round2 = [
            r for r in results_round2
            if isinstance(r, dict) and r.get("success")
        ]

        logger.info(f"Round 2 complete: {len(successful_round2)} agents refined")
        all_results.extend(successful_round2)

    return {
        "total_agents": len(all_results),
        "results": all_results,
        "rounds": rounds
    }


def weighted_synthesis(results: List[Dict], user_message: str) -> Dict:
    if not results:
        return {
            "synthesis": "Nem sikerült eredményt generálni.",
            "confidence": 0.0,
            "top_reasoning": []
        }

    weighted_results = []

    for r in results:
        weight = 1.0

        if r.get("agent_id", 0) >= 15:
            weight *= 1.5

        reasoning_len = len(r.get("reasoning", ""))
        if reasoning_len > 1000:
            weight *= 1.5
        elif reasoning_len > 500:
            weight *= 1.2

        content_len = len(r.get("content", ""))
        if content_len > 1000:
            weight *= 1.3

        weighted_results.append({
            "result": r,
            "weight": weight
        })

    weighted_results.sort(key=lambda x: x["weight"], reverse=True)

    top_3 = weighted_results[:3]

    synthesis_parts = []
    total_weight = sum(wr["weight"] for wr in top_3)

    for i, wr in enumerate(top_3, 1):
        contribution = (wr["weight"] / total_weight) * 100
        synthesis_parts.append(
            f"**Agent {wr['result']['agent_id']}** (hozzájárulás: {contribution:.1f}%):\n\n"
            f"{wr['result']['content']}\n"
        )

    all_reasoning = [
        {
            "agent_id": r["agent_id"],
            "reasoning": r.get("reasoning", "")[:1000]
        }
        for r in results[:5]
    ]

    return {
        "synthesis": "\n\n---\n\n".join(synthesis_parts),
        "top_reasoning": all_reasoning,
        "total_agents": len(results),
        "confidence": min(len(results) / 15, 1.0)
    }


@app.route("/")
def index():
    return send_from_directory(".", "index-2.html")


@app.route("/api/chat", methods=["POST"])
def chat():
    data = request.get_json()
    user_message = data.get("message", "")
    num_agents = data.get("num_agents", 15)
    rounds = data.get("rounds", 2)
    temperature = data.get("temperature", 0.8)
    session_id = data.get("session_id", "default")

    if not user_message:
        return jsonify({"error": "Message is required"}), 400

    if session_id not in conversation_history:
        conversation_history[session_id] = []

    conversation_history[session_id].append({
        "role": "user",
        "content": user_message
    })

    def generate():
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)

        try:
            yield f"data: {json.dumps({'type': 'status', 'content': f'🚀 {num_agents} agent indítása...'})}\n\n"

            multi_result = loop.run_until_complete(
                multi_agent_consensus(
                    user_message,
                    num_agents,
                    rounds,
                    conversation_context=conversation_history[session_id][-10:],
                    temperature=temperature
                )
            )

            for result in multi_result["results"]:
                if result.get("success"):
                    if result.get("reasoning"):
                        payload = json.dumps({
                            "type": "reasoning",
                            "agent_id": result["agent_id"],
                            "content": result["reasoning"]
                        })
                        yield f"data: {payload}\n\n"

                    payload = json.dumps({
                        "type": "agent_response",
                        "agent_id": result["agent_id"],
                        "content": result["content"]
                    })
                    yield f"data: {payload}\n\n"

            yield f"data: {json.dumps({'type': 'status', 'content': '🔮 Szintézis készítése...'})}\n\n"

            synthesis = weighted_synthesis(multi_result["results"], user_message)

            for reasoning_item in synthesis["top_reasoning"]:
                payload = json.dumps({
                    "type": "synthesis_reasoning",
                    "agent_id": reasoning_item["agent_id"],
                    "content": reasoning_item["reasoning"]
                })
                yield f"data: {payload}\n\n"

            final_content = synthesis["synthesis"]

            conversation_history[session_id].append({
                "role": "assistant",
                "content": final_content
            })

            payload = json.dumps({
                "type": "synthesis",
                "content": final_content,
                "confidence": synthesis["confidence"],
                "total_agents": synthesis["total_agents"]
            })
            yield f"data: {payload}\n\n"

        except Exception as e:
            logger.error(f"Chat error: {str(e)}")
            error_payload = json.dumps({
                "type": "error",
                "content": f"Hiba történt: {str(e)}"
            })
            yield f"data: {error_payload}\n\n"

        finally:
            loop.close()
            yield "data: [DONE]\n\n"

    return Response(generate(), mimetype="text/event-stream")


@app.route("/api/health", methods=["GET"])
def health():
    return jsonify({
        "status": "healthy",
        "agents": len(agents),
        "api_keys_configured": len(API_KEYS),
        "timestamp": datetime.now().isoformat()
    })


@app.route("/api/reset", methods=["POST"])
def reset_conversation():
    data = request.get_json()
    session_id = data.get("session_id", "default")

    if session_id in conversation_history:
        conversation_history[session_id] = []

    return jsonify({
        "status": "success",
        "message": "Conversation reset"
    })


if __name__ == "__main__":
    logger.info(f"Multi-Agent System indítása...")
    logger.info(f"Elérhető agensek: {len(agents)}")
    logger.info(f"Konfigurált API kulcsok: {len(API_KEYS)}")

    app.run(host="0.0.0.0", port=5000, debug=False)
