            #user-input {
                flex: 1;
                background: var(--shade-80);
                border: 1px solid var(--border-dim);
                color: var(--text-main);
                padding: 0.75rem 1rem;
                border-radius: 0.75rem;
                font-size: 1rem;
                resize: none;
                max-height: 150px;
                transition: all 0.2s;
            }

            #user-input:focus {
                outline: none;
                border-color: var(--color-base);
                box-shadow: 0 0 0 3px rgba(255, 18, 126, 0.1);
            }

            #user-input::placeholder {
                color: var(--text-muted);
            }

            #send-btn {
                background: linear-gradient(135deg, var(--color-base), var(--shade-30));
                color: white;
                border: none;
                padding: 0.75rem 1.5rem;
                border-radius: 0.75rem;
                font-weight: 600;
                cursor: pointer;
                transition: all 0.2s;
                flex-shrink: 0;
            }

            #send-btn:hover:not(:disabled) {
                transform: translateY(-2px);
                box-shadow: 0 8px 20px rgba(255, 18, 126, 0.4);
            }

            #send-btn:disabled {
                background: var(--shade-70);
                cursor: not-allowed;
                opacity: 0.5;
            }

            strong {
                color: var(--color-base);
                font-weight: 700;
