            em {
                color: var(--tint-40);
                font-style: italic;
            }

            h2, h3 {
                color: var(--color-base);
                margin: 1rem 0 0.5rem 0;
            }

            @media (max-width: 768px) {
                #header h1 {
                    font-size: 1rem;
                }

                #controls-btn {
                    padding: 0.375rem 0.75rem;
                    font-size: 0.75rem;
