    </head>
    <body>
        <div id="app">
            <div id="header">
                <h1>🤖 Multi-Agent GLM-4.7</h1>
                <button id="controls-btn">⚙️ Beállítások</button>
            </div>

            <div id="controls-panel">
                <div id="controls-content">
                    <h2 style="margin-bottom: 1.5rem; color: var(--color-base);">Beállítások</h2>

                    <div class="control-group">
                        <label for="num-agents">
                            Agensek száma:
                            <span class="control-value" id="num-agents-value">15</span>
                        </label>
                        <input type="range" id="num-agents" min="3" max="15" value="15" step="1">
                    </div>

                    <div class="control-group">
                        <label for="num-rounds">
                            Reasoning körök:
                            <span class="control-value" id="num-rounds-value">2</span>
                        </label>
                        <input type="range" id="num-rounds" min="1" max="3" value="2" step="1">
                    </div>

                    <div class="control-group">
                        <label for="temperature">
                            Hőmérséklet:
                            <span class="control-value" id="temperature-value">0.8</span>
                        </label>
                        <input type="range" id="temperature" min="0.1" max="2.0" value="0.8" step="0.1">
                    </div>

                    <button id="close-controls">Bezárás</button>
                </div>
            </div>

            <div id="chat-container"></div>

            <div id="input-area">
                <form id="input-form">
                    <textarea
                        id="user-input"
                        placeholder="Írj egy üzenetet..."
                        rows="1"
                        autocomplete="off"
                    ></textarea>
                    <button type="submit" id="send-btn">Küldés</button>
                </form>
            </div>
        </div>

        <script>
            const chatContainer = document.getElementById('chat-container');
            const userInput = document.getElementById('user-input');
            const sendBtn = document.getElementById('send-btn');
            const inputForm = document.getElementById('input-form');

            const controlsBtn = document.getElementById('controls-btn');
            const controlsPanel = document.getElementById('controls-panel');
            const closeControlsBtn = document.getElementById('close-controls');

            const numAgentsSlider = document.getElementById('num-agents');
            const numAgentsValue = document.getElementById('num-agents-value');
            const numRoundsSlider = document.getElementById('num-rounds');
            const numRoundsValue = document.getElementById('num-rounds-value');
            const temperatureSlider = document.getElementById('temperature');
            const temperatureValue = document.getElementById('temperature-value');

            const sessionId = Math.random().toString(36).substring(7);

            let isProcessing = false;

            numAgentsSlider.addEventListener('input', (e) => {
                numAgentsValue.textContent = e.target.value;
            });

            numRoundsSlider.addEventListener('input', (e) => {
                numRoundsValue.textContent = e.target.value;
            });

            temperatureSlider.addEventListener('input', (e) => {
                temperatureValue.textContent = parseFloat(e.target.value).toFixed(1);
            });

            controlsBtn.addEventListener('click', () => {
                controlsPanel.classList.add('active');
            });

            closeControlsBtn.addEventListener('click', () => {
                controlsPanel.classList.remove('active');
            });

            controlsPanel.addEventListener('click', (e) => {
                if (e.target === controlsPanel) {
                    controlsPanel.classList.remove('active');
                }
            });

            userInput.addEventListener('input', function() {
                this.style.height = 'auto';
                this.style.height = Math.min(this.scrollHeight, 150) + 'px';
            });

            function addMessage(content, className) {
                const messageDiv = document.createElement('div');
                messageDiv.className = `message ${className}`;
                messageDiv.innerHTML = content;
                chatContainer.appendChild(messageDiv);
                chatContainer.scrollTop = chatContainer.scrollHeight;
                return messageDiv;
            }

            function formatMarkdown(text) {
                return text
                    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
                    .replace(/\*(.+?)\*/g, '<em>$1</em>')
                    .replace(/##\s+(.+)/g, '<h2>$1</h2>')
                    .replace(/###\s+(.+)/g, '<h3>$1</h3>')
                    .replace(/\n/g, '<br>');
            }

            async function sendMessage(message) {
                if (!message.trim() || isProcessing) return;

                isProcessing = true;

                const numAgents = parseInt(numAgentsSlider.value);
                const rounds = parseInt(numRoundsSlider.value);
                const temperature = parseFloat(temperatureSlider.value);

                addMessage(formatMarkdown(message), 'user-message');
                userInput.value = '';
                userInput.style.height = 'auto';
                sendBtn.disabled = true;

                try {
                    const response = await fetch('/api/chat', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                        body: JSON.stringify({
                            message: message,
                            num_agents: numAgents,
                            rounds: rounds,
                            temperature: temperature,
                            session_id: sessionId
                        }),
                    });

                    const reader = response.body.getReader();
                    const decoder = new TextDecoder();

                    let currentReasoningDiv = null;
                    let currentAgentDiv = null;
                    let currentSynthesisDiv = null;
                    let agentReasonings = {};

                    while (true) {
                        const { value, done } = await reader.read();
                        if (done) break;

                        const chunk = decoder.decode(value);
                        const lines = chunk.split('\n');

                        for (const line of lines) {
                            if (line.startsWith('data: ')) {
                                const data = line.slice(6);
                                if (data === '[DONE]') continue;

                                try {
                                    const parsed = JSON.parse(data);

                                    if (parsed.type === 'status') {
                                        addMessage(parsed.content, 'status-message');
                                    }
                                    else if (parsed.type === 'reasoning') {
                                        if (!agentReasonings[parsed.agent_id]) {
                                            agentReasonings[parsed.agent_id] = '';
                                            currentReasoningDiv = document.createElement('div');
                                            currentReasoningDiv.className = 'message reasoning';
                                            currentReasoningDiv.dataset.agentId = parsed.agent_id;
                                            chatContainer.appendChild(currentReasoningDiv);
                                        }
                                        agentReasonings[parsed.agent_id] += parsed.content;
                                        currentReasoningDiv.innerHTML = `<span class="agent-badge">Agent ${parsed.agent_id}</span><br>${formatMarkdown(agentReasonings[parsed.agent_id])}`;
                                        chatContainer.scrollTop = chatContainer.scrollHeight;
                                    }
                                    else if (parsed.type === 'agent_response') {
                                        currentAgentDiv = document.createElement('div');
                                        currentAgentDiv.className = 'message agent-response';
                                        currentAgentDiv.innerHTML = `<span class="agent-badge">Agent ${parsed.agent_id}</span><br>${formatMarkdown(parsed.content)}`;
                                        chatContainer.appendChild(currentAgentDiv);
                                        chatContainer.scrollTop = chatContainer.scrollHeight;
                                    }
                                    else if (parsed.type === 'synthesis_reasoning') {
                                        const reasoningDiv = document.createElement('div');
                                        reasoningDiv.className = 'message reasoning';
                                        reasoningDiv.innerHTML = `<span class="agent-badge">Agent ${parsed.agent_id}</span><br>${formatMarkdown(parsed.content)}`;
                                        chatContainer.appendChild(reasoningDiv);
                                        chatContainer.scrollTop = chatContainer.scrollHeight;
                                    }
                                    else if (parsed.type === 'synthesis') {
                                        currentSynthesisDiv = document.createElement('div');
                                        currentSynthesisDiv.className = 'message synthesis';

                                        const confidence = Math.round(parsed.confidence * 100);

                                        currentSynthesisDiv.innerHTML = `
                                            <h2>🎯 Végső Szintézis (${parsed.total_agents} agent alapján)</h2>
                                            <div class="synthesis-content">${formatMarkdown(parsed.content)}</div>
                                            <div style="margin-top: 1rem; color: var(--text-muted); font-size: 0.875rem;">
                                                Konfidencia: ${confidence}%
                                            </div>
                                            <div class="confidence-bar">
                                                <div class="confidence-fill" style="width: ${confidence}%"></div>
                                            </div>
                                        `;
                                        chatContainer.appendChild(currentSynthesisDiv);
                                        chatContainer.scrollTop = chatContainer.scrollHeight;
                                    }
                                    else if (parsed.type === 'error') {
                                        addMessage(`❌ ${parsed.content}`, 'status-message');
                                    }
                                } catch (e) {
                                    console.error('Parse error:', e);
                                }
                            }
                        }
                    }
                } catch (error) {
                    addMessage(`❌ Hiba: ${error.message}`, 'status-message');
                } finally {
                    isProcessing = false;
                    sendBtn.disabled = false;
                    userInput.focus();
                }
            }

            inputForm.addEventListener('submit', (e) => {
                e.preventDefault();
                const message = userInput.value.trim();
                if (message) {
                    sendMessage(message);
                }
            });

            userInput.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    inputForm.dispatchEvent(new Event('submit'));
                }
            });

            addMessage(
                '👋 Üdvözöllek a Multi-Agent GLM-4.7 rendszerben!<br><br>' +
                '💡 15 független AI agent dolgozik együtt a kérdéseiden<br>' +
                '🔄 2 körös reasoning: önálló gondolkodás → kereszt-validáció<br>' +
                '🎯 Súlyozott szintézis a legjobb eredményért<br><br>' +
                'Tegyél fel bármilyen összetett kérdést!',
                'status-message'
            );

            userInput.focus();
        </script>
    </body>
</html>
